			t.Fatal("expected a SessionEnd hook to be installed")
		}
		if got := settings.Hooks.SessionEnd[0].Hooks[0].Timeout; got != 0 {
			t.Errorf("production SessionEnd timeout = %d, want 0 (dev-only)", got)
		}
	})
}

